                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    cells.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(cells) >= 2:
                    runs.append((color, cells))
        runs_by_direction.append(runs)

    idx = max(range(len(directions)),
              key=lambda i: sum(len(cells) for _, cells in runs_by_direction[i]))
    runs = runs_by_direction[idx]
    if not runs:
        return [row[:] for row in grid]

    dr, dc = directions[idx]
    if (dr, dc) == (0, 1):
        across = lambda p: p[0]
    elif (dr, dc) == (1, 0):
        across = lambda p: p[1]
    elif (dr, dc) == (1, 1):
        across = lambda p: p[0] - p[1]
    else:
        across = lambda p: p[0] + p[1]

    ordered = sorted(runs, key=lambda item: across(item[1][0]))
    target = len(ordered[len(ordered) // 2][1])

    starts = [cells[0] for _, cells in runs]
    ends = [cells[-1] for _, cells in runs]
    start_align = max(Counter(r * dr + c * dc for r, c in starts).values())
